INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(701, 'Genesis 26:22', 'Genesis', 26, 22, '&nbsp;هغه د دې ځائ نه لاړو او يو بل کوهے يې وکنستلو. او په هغې باندې هيڅ لانجه جوړه نۀ شوه، نو هغۀ په دې کوهى باندې ”رحوبوت“ نوم کېښودو. هغۀ وفرمائيل، ”مالِک خُدائ اوس زمونږ دپاره يو ځائ جوړ کړے دے چې په دې مُلک کښې اوسيږو او مونږ به دلته آباد شُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(702, 'Genesis 26:23', 'Genesis', 26, 23, '&nbsp;اِسحاق د دې ځائ نه بيرسبع ته لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(703, 'Genesis 26:24', 'Genesis', 26, 24, '&nbsp;په هغه شپه مالِک خُدائ هغۀ ته راڅرګند شو او ورته يې وفرمائيل، ”زۀ ستا د پلار اِبراهيم خُدائ پاک يم. يرېږه مه، زۀ ستا مل يم. زۀ به تا له برکت درکړم او د خپل خِدمت کوونکى اِبراهيم سره زما د وعدې په ذريعه به تا له ډېر اولاد درکوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(704, 'Genesis 26:25', 'Genesis', 26, 25, '&nbsp;اِسحاق هلته يوه قربان‌ګاه جوړه کړه او د مالِک خُدائ عبادت يې وکړو. بيا هغۀ هلته خپله خېمه ولګوله او د هغۀ نوکرانو بل کوهے وکنستلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(705, 'Genesis 26:26', 'Genesis', 26, 26, '&nbsp;ابى‌مَلِک د جرار نه د خپل مشير اخوزت او د خپل لښکر مشر فيکُل سره د اِسحاق سره مِلاوېدو دپاره راغلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(706, 'Genesis 26:27', 'Genesis', 26, 27, '&nbsp;نو اِسحاق ترې تپوس وکړو، ”تۀ اوس ما سره مِلاوېدو له ولې راغلے يې، چې تۀ مخکښې ما سره ډېر بد وې او زۀ دې د خپل مُلک نه بهر کړم؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(707, 'Genesis 26:28', 'Genesis', 26, 28, '&nbsp;هغوئ جواب ورکړو چې، ”مونږ ته صفا پته ولګېده چې مالِک خُدائ ستا مل دے او زمونږ خيال دا دے چې زمونږ په مينځ کښې يو پوخ لوظ په کار دے. مونږ تا سره لوظ کول غواړُو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(708, 'Genesis 26:29', 'Genesis', 26, 29, '&nbsp;چې تۀ به مونږ ته نقصان نۀ رسوې، لکه چې څنګه مونږ تا ته نقصان نۀ دے رسولے، او مونږ هيڅ بد تا سره نۀ دى کړى او په امن سره ژوند تېرولو ته مو پرېښودلے وې. او بې‌شکه چې مالِک خُدائ تا له برکت درکړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(709, 'Genesis 26:30', 'Genesis', 26, 30, '&nbsp;اِسحاق هغوئ له غټه مېلمستيا وکړه او هغوئ خوراک څښاک وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(710, 'Genesis 26:31', 'Genesis', 26, 31, '&nbsp;هغوئ سحر وختى پاڅېدل او يو بل ته يې قسمونه وکړل. اِسحاق هغوئ رُخصت کړل او هغوئ د هغۀ نه په سلامتۍ سره لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(711, 'Genesis 26:32', 'Genesis', 26, 32, '&nbsp;هم په هغه ورځ د اِسحاق نوکران راغلل او هغۀ ته يې د هغه کوهى په حقله ووئيل چې کوم هغوئ کنستلے وو. هغوئ ووئيل، ”مونږ اوبۀ موندلې دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(712, 'Genesis 26:33', 'Genesis', 26, 33, '&nbsp;هغۀ په هغه کوهى ”سبع“ نوم کېښودو. او تر ننه پورې د هغه ښار نوم بيرسبع دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(713, 'Genesis 26:34', 'Genesis', 26, 34, '&nbsp;چې کله عِيسو د څلوېښتو کالو وو، هغۀ دوه حِتۍ ښځې د بيرۍ لور يهودِت او د ايلون لور باسمت وادۀ کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(714, 'Genesis 26:35', 'Genesis', 26, 35, '&nbsp;هغوئ د اِسحاق او رِبقه ژوند تريخ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(715, 'Genesis 27:1', 'Genesis', 27, 1, '&nbsp;چې کله اِسحاق ضعيف شو او نظر يې کار پرېښودو، هغۀ خپل مشر زوئ عِيسو راوغوښتو او هغۀ ته يې وفرمائيل، ”اے زما زويه.“ هغۀ جواب ورکړو، ”جى، زۀ حاضر يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(716, 'Genesis 27:2', 'Genesis', 27, 2, '&nbsp;اِسحاق ورته وفرمائيل چې، ”ګوره، زۀ ضعيف يم او کېدے شى چې زر وفات شم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(717, 'Genesis 27:3', 'Genesis', 27, 3, '&nbsp;خپل غشى او لينده راواخله، بهر پټو ته لاړ شه او زما دپاره ښکار وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(718, 'Genesis 27:4', 'Genesis', 27, 4, '&nbsp;ما له زما د خوښې مزېدار خوراک پوخ کړه او ما له يې راوړه. چې کله هغه زۀ وخورم، نو زۀ به تا له زما د مرګ نه مخکښې خپل آخرى برکت درکړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(719, 'Genesis 27:5', 'Genesis', 27, 5, '&nbsp;چې کله اِسحاق عِيسو ته دا خبرې کولې، نو رِبقې اورېدلې. او چې عِيسو پټو ته ښکار دپاره لاړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(720, 'Genesis 27:6', 'Genesis', 27, 6, '&nbsp;نو رِبقې يعقوب ته ووئيل، ”ګوره، ما ستا د پلار نه د عِيسو سره دا خبرې واورېدې چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(721, 'Genesis 27:7', 'Genesis', 27, 7, '&nbsp;ما له د ښکار غوښه راوړه او ما له يې پخه کړه. چې کله هغه وخورم، نو د مرګ نه مخکښې به د مالِک خُدائ په وړاندې خپل برکت تا له درکړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(722, 'Genesis 27:8', 'Genesis', 27, 8, '&nbsp;رِبقې ورته وئيل، ”اوس زما زويه، زما خبره واوره او چې څۀ درته وايم هم هغه شان وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(723, 'Genesis 27:9', 'Genesis', 27, 9, '&nbsp;رَمې ته لاړ شه او دوه څاربۀ د چېلۍ بچى راونيسه، نو زۀ به ترې مزېدار خوراک پوخ کړم کوم خوراک چې ستا د پلار ډېر خوښ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(724, 'Genesis 27:10', 'Genesis', 27, 10, '&nbsp;هغه تۀ خپل پلار له يوسه چې يې وخورى، نو د مرګ نه مخکښې به هغه تا له خپل برکت درکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(725, 'Genesis 27:11', 'Genesis', 27, 11, '&nbsp;خو يعقوب خپلې مور ته وفرمائيل، ”تا ته پته ده چې د عِيسو په څرمن وېښتۀ شته خو زما په څرمن وېښتۀ نشته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(726, 'Genesis 27:12', 'Genesis', 27, 12, '&nbsp;کېدے شى چې زما پلار ما له لاس راوړى او هغۀ ته پته ولګى چې زۀ يې دوکه کوم، نو زۀ به په خپل ځان د برکت په ځائ لعنت راوړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(727, 'Genesis 27:13', 'Genesis', 27, 13, '&nbsp;د هغۀ مور ورته ووئيل، ”زما زويه، ستا لعنت دې په ما شى، بس هغه څۀ وکړه څۀ چې زۀ درته وايم، لاړ شه او ما له د چېلۍ بچى راوله.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(728, 'Genesis 27:14', 'Genesis', 27, 14, '&nbsp;نو هغه لاړو او هغه يې راونيول او خپلې مور له يې راوستل او د هغۀ مور هغه مزېدار خوراک پوخ کړو کوم چې د هغۀ د پلار ډېر خوښ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(729, 'Genesis 27:15', 'Genesis', 27, 15, '&nbsp;بيا هغې د عِيسو هغه خاص جامې راواخستلې، چې کومې هغې ورله په کور کښې ساتلې وې او خپل کشر زوئ يعقوب ته يې ورواغوستلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(730, 'Genesis 27:16', 'Genesis', 27, 16, '&nbsp;هغې د چېلۍ د بچو څرمنې د هغۀ لاسونو او د هغۀ څټ ته هم ورواغوستلې چرته چې وېښتۀ نۀ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(731, 'Genesis 27:17', 'Genesis', 27, 17, '&nbsp;رِبقې هغۀ له هغه مزېدار خوراک ورکړو او چې کومه روټۍ يې پخه کړې وه هغه يې هم ورکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(732, 'Genesis 27:18', 'Genesis', 27, 18, '&nbsp;بيا يعقوب خپل پلار له ورَغلو او ورته يې ووئيل، ”زما پلاره.“ هغۀ جواب ورکړو، ”ښه، تۀ زما کوم زوئ يې؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(733, 'Genesis 27:19', 'Genesis', 27, 19, '&nbsp;يعقوب جواب ورکړو، ”زۀ ستا مشر زوئ عِيسو يم، ما هم هغه شان کړى دى چې څنګه تا ما ته وفرمائيل. اوس لږ کښېنه او د ښکار غوښه وخوره چې کومه ما درله راوړې ده، نو تۀ به ما له خپل برکت راکړې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(734, 'Genesis 27:20', 'Genesis', 27, 20, '&nbsp;اِسحاق ورته وفرمائيل، ”زما زويه، دومره زر تا ښکار څنګه وکړو؟“ يعقوب جواب ورکړو، ”مالِک خُدائ، ستا خُدائ پاک زۀ کامياب کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(735, 'Genesis 27:21', 'Genesis', 27, 21, '&nbsp;اِسحاق يعقوب ته وفرمائيل، ”زما زويه، لږ رانزدې شه چې تا له لاس دروړم. تۀ په رښتيا عِيسو يې څۀ؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(736, 'Genesis 27:22', 'Genesis', 27, 22, '&nbsp;يعقوب خپل پلار ته ورنزدې شو، هغۀ له يې لاس وروړو او وې فرمائيل چې، ”ستا آواز د يعقوب د آواز په شان دے، خو ستا لاسونه د عِيسو د لاسونو په شان دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(737, 'Genesis 27:23', 'Genesis', 27, 23, '&nbsp;هغۀ يعقوب ونۀ پېژندلو، ځکه چې د هغۀ لاسونه د عِيسو په شان د وېښتو نه ډک وُو. يعقوب هغۀ له د برکت په ورکولو وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(738, 'Genesis 27:24', 'Genesis', 27, 24, '&nbsp;خو چې بيا يې ترې نه تپوس وکړو، ”تۀ په رښتيا عِيسو يې؟“ هغۀ جواب ورکړو، ”آو، زۀ عِيسو يم کنه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(739, 'Genesis 27:25', 'Genesis', 27, 25, '&nbsp;اِسحاق وفرمائيل، ”ما له د ښکار غوښه لږه رانزدې کړه. چې زۀ هغه وخورم، زۀ به تا له خپل برکت درکړم.“ يعقوب ورله هغه راوړه او هغۀ ورله څۀ مے هم څښلو له راوړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(740, 'Genesis 27:26', 'Genesis', 27, 26, '&nbsp;بيا د هغۀ پلار هغۀ ته وفرمائيل، ”زما زويه، رانزدې شه او ښُکل مې کړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(741, 'Genesis 27:27', 'Genesis', 27, 27, '&nbsp;چې هغه ښُکلولو له ورته راغلو په اِسحاق د هغۀ د جامو بوئ ولګېدو، نو هغۀ خپل برکت ورکړو. هغۀ وفرمائيل، ”واه واه، زما د زوئ وږمه د پټو د بوئ په شان ده کوم له چې مالِک خُدائ برکت ورکړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(742, 'Genesis 27:28', 'Genesis', 27, 28, '&nbsp;خُدائ پاک دې تا له د آسمان نه پرخه درکړى او ستا زمکه دې شنه کړى، هغه دې تا له ډېره زياته غله او مے درکړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(743, 'Genesis 27:29', 'Genesis', 27, 29, '&nbsp;قومونه دې ستا خِدمتګاران شى او خلق دې ستا په مخکښې ټيټ شى. تۀ دې په خپلو خلقو حکومت وکړې او ستا د مور اولاد دې تا ته ټيټ شى. چې په تا څوک لعنت وائى په هغوئ دې لعنت وى او چې څوک تا له برکت غواړى په هغوئ دې برکت وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(744, 'Genesis 27:30', 'Genesis', 27, 30, '&nbsp;چې کله اِسحاق خپل برکت ورکول ختم کړل، نو چې څنګه يعقوب لاړو، نو د هغۀ ورور عِيسو د ښکار نه راغلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(745, 'Genesis 27:31', 'Genesis', 27, 31, '&nbsp;هغۀ هم مزېدار خوراک پوخ کړو او هغه يې خپل پلار له راوړو. هغۀ وفرمائيل، ”پلاره، لږ راپاڅه او د ښکار غوښه وخوره چې کومه ما تا له راوړې ده، نو چې تۀ ما له خپل برکت راکړې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(746, 'Genesis 27:32', 'Genesis', 27, 32, '&nbsp;اِسحاق تپوس وکړو، ”تۀ څوک يې؟“ هغۀ جواب ورکړو، ”ستا مشر زوئ عِيسو يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(747, 'Genesis 27:33', 'Genesis', 27, 33, '&nbsp;اِسحاق ويرېدو او ټول رپېدلو او هغۀ تپوس وکړو، ”نو بيا هغه څوک وو، چې ښکار يې وکړو او هغه غوښه يې ما له راوړه؟ ستا د راتلو نه لږ مخکښې ما هغه وخوړه. ما هغۀ له خپل آخرى برکت ورکړو، نو دا د هغۀ د همېشه دپاره دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(748, 'Genesis 27:34', 'Genesis', 27, 34, '&nbsp;چې کله عِيسو دا واورېدل، هغۀ ډېر په چغو چغو وژړل او وې فرمائيل، ”اے پلاره، ما له هم خپل برکت راکړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(749, 'Genesis 27:35', 'Genesis', 27, 35, '&nbsp;اِسحاق جواب ورکړو، ”ستا ورور راغلو او دوکه يې کړم. هغۀ ستا برکت وړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(750, 'Genesis 27:36', 'Genesis', 27, 36, '&nbsp;عِيسو وفرمائيل، ”په دې کښې هيڅ شک نشته د هغۀ نوم يعقوب دے. دا دوېم ځل دے چې هغۀ زما ځائ په چل نيولے دے، اول يې زما د مشرۍ حق واخستو او اوس يې زما برکت هم واخستو. تا زما دپاره برکت نۀ دے پرېښے څۀ؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(751, 'Genesis 27:37', 'Genesis', 27, 37, '&nbsp;اِسحاق جواب وکړو، ”ما هغه په تا اختيارمن کړے دے او ما د هغۀ ټول خپلوان د هغۀ نوکران کړى دى. ما هغۀ له غله او مے ورکړى دى. زما زويه، اوس داسې هيڅ هم نشته چې ستا دپاره يې زۀ وکړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(752, 'Genesis 27:38', 'Genesis', 27, 38, '&nbsp;عِيسو خپل پلار ته سوال زارى کوله، ”پلاره، تا سره صِرف يو برکت وو څۀ؟ پلاره، ما له هم برکت راکړه.“ هغۀ ډېره زياته ژړا شروع کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(753, 'Genesis 27:39', 'Genesis', 27, 39, '&nbsp;بيا اِسحاق هغۀ ته وفرمائيل، ”ستا دپاره به د آسمان نه پرخه نۀ وى، ستا دپاره به زمکه شنه نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(754, 'Genesis 27:40', 'Genesis', 27, 40, '&nbsp;تۀ به د خپلې تُورې په زور ژوند تېروې، خو د خپل ورور به تۀ غلام يې. چې کله تۀ باغى شې، نو د هغۀ پړى به وشلوې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(755, 'Genesis 27:41', 'Genesis', 27, 41, '&nbsp;عِيسو د يعقوب سره کينه ساتله، ځکه چې د هغۀ پلار، يعقوب له د هغۀ برکت ورکړے وو. هغۀ د خپل ځان سره وفرمائيل، ”زما د پلار مرګ نزدې دے، چې کله زما پلار وفات شى نو بيا به زۀ يعقوب ووژنم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(756, 'Genesis 27:42', 'Genesis', 27, 42, '&nbsp;خو رِبقه د خپل مشر زوئ عِيسو د دې خبرې نه خبر شوه، نو هغې يعقوب راوغوښتلو او ورته يې ووئيل، ”دا خبره واوره. ستا ورور عِيسو بدل اخستل غواړى او تا وژل غواړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(757, 'Genesis 27:43', 'Genesis', 27, 43, '&nbsp;نو زما زويه، څۀ چې زۀ درته وايم هم هغه شان وکړه. سمدستى لابن له وتښته چې په حاران کښې دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(758, 'Genesis 27:44', 'Genesis', 27, 44, '&nbsp;او د هغۀ سره د څۀ وخت دپاره پاتې شه، چې ستا د ورور غصه سړه شى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(759, 'Genesis 27:45', 'Genesis', 27, 45, '&nbsp;او چې د هغۀ هغه څۀ هېر شى چې تا ورسره کړى دى. بيا به زۀ څوک درولېږم چې تا واپس راولى. زۀ دې خپل دواړه زامن په يوه ورځ ولې بايلم؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(760, 'Genesis 27:46', 'Genesis', 27, 46, '&nbsp;رِبقې اِسحاق ته ووئيل، ”زۀ د عِيسو د بل مُلک د ښځو په وجه په خپل ژوند کښې تنګه يم. کۀ يعقوب هم د دې مُلک د حِتۍ ښځو نه د يوې حِتۍ ښځې سره وادۀ وکړو، نو د دې نه به بيا زما دپاره مرګ ښۀ وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(761, 'Genesis 28:1', 'Genesis', 28, 1, '&nbsp;اِسحاق يعقوب راوغوښتلو، په مخه ښه يې ورته ووئيل او هغۀ له يې حُکم ورکړو، ”د يوې کنعانۍ جينۍ سره وادۀ ونۀ کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(762, 'Genesis 28:2', 'Genesis', 28, 2, '&nbsp;سمدستى مسوپتاميه ته، د خپل نيکۀ بتو‌اېل کور ته لاړ شه او هلته د خپل ماما لابن د لوڼو نه يوې سره وادۀ وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(763, 'Genesis 28:3', 'Genesis', 28, 3, '&nbsp;قادر خُدائ دې ستا وادۀ بختور کړى او ډېر اولاد دې درکړى، نو تۀ به د ډېرو قومونو پلار شې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(764, 'Genesis 28:4', 'Genesis', 28, 4, '&nbsp;هغه دې تا او ستا اولاد له برکت درکړى لکه څنګه چې هغۀ اِبراهيم له برکت ورکړے وو. او دا مُلک دې ستا شى، چې په کوم کښې تۀ مسافر وې او چې کوم خُدائ پاک اِبراهيم له ورکړے وو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(765, 'Genesis 28:5', 'Genesis', 28, 5, '&nbsp;نو ځکه اِسحاق يعقوب په مسوپتاميه کښې، لابن له ولېږلو، چې هغه د بتو‌اېل آرامى زوئ وو او د رِبقې ورور وو، کومه چې د يعقوب او عِيسو مور وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(766, 'Genesis 28:6', 'Genesis', 28, 6, '&nbsp;عِيسو ته دا پته ولګېده چې اِسحاق يعقوب له برکت ورکړے وو او د ښځې لټولو دپاره يې هغه مسوپتاميه ته لېږلے دے. هغۀ ته دا هم پته وه چې کله اِسحاق هغۀ له برکت ورکړو نو يعقوب له يې حُکم ورکړو چې، ”د يوې کنعانۍ ښځې سره به وادۀ نۀ کوې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(767, 'Genesis 28:7', 'Genesis', 28, 7, '&nbsp;هغۀ ته پته ولګېده چې يعقوب د خپل پلار او مور خبره منلې ده او مسوپتاميه ته تلے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(768, 'Genesis 28:8', 'Genesis', 28, 8, '&nbsp;نو عِيسو پوهه شو چې د هغۀ د پلار اِسحاق کنعانۍ ښځې خوښې نۀ دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(769, 'Genesis 28:9', 'Genesis', 28, 9, '&nbsp;نو هغه د اِبراهيم زوئ اِسمٰعيل له لاړو او د هغۀ لور محلت سره يې وادۀ وکړو، چې هغه د نبايوت خور وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(770, 'Genesis 28:10', 'Genesis', 28, 10, '&nbsp;يعقوب د بيرسبع نه لاړو او د حاران په طرف روان شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(771, 'Genesis 28:11', 'Genesis', 28, 11, '&nbsp;نمر په پرېوتو وو چې هغه يو خاص ځائ ته راغلو او په هغه شپه هلته پاتې شو. هغه د خوب دپاره څملاستو او خپل سر يې په يو کاڼے کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(772, 'Genesis 28:12', 'Genesis', 28, 12, '&nbsp;هغۀ په خوب کښې وليدل چې يوه پوړۍ د زمکې نه آسمان پورې ختلې ده او دا يې هم وليدل چې د خُدائ پاک فرښتې په دې باندې بره ښکته، ختلې او راکوزېدلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(773, 'Genesis 28:13', 'Genesis', 28, 13, '&nbsp;او ګوره، هغۀ په خوب کښې وليدل چې مالِک خُدائ د هغۀ سره ولاړ وو. هغۀ وفرمائيل، ”زۀ مالِک خُدائ يم، د اِبراهيم او د اِسحاق خُدائ پاک يم، زۀ به تا او ستا اولاد له دا زمکه ورکوم چې په کومه تۀ ملاست يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(774, 'Genesis 28:14', 'Genesis', 28, 14, '&nbsp;هغوئ به د زمکې د شګو په شان زيات شى. دوئ به خپله علاقه په هر طرف خوره کړى، ستا او ستا د اولاد په وجه به زۀ د دُنيا ټولو قومونو له برکت ورکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(775, 'Genesis 28:15', 'Genesis', 28, 15, '&nbsp;ياد ساته، زۀ به ستا مل يم او چې چرته هم ځې نو زۀ به ستا حِفاظت کوم او زۀ به تا واپس دې زمکې ته راولم. زۀ به تا تر هغې پورې نۀ پرېږدم چې ما تا سره خپله وعده پوره کړې نۀ وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(776, 'Genesis 28:16', 'Genesis', 28, 16, '&nbsp;يعقوب د خوب نه پاڅېدو او وې فرمائيل، ”بې‌شکه چې مالِک خُدائ دلته دے، هغه په دې ځائ کښې دے، خو ما ته پته نۀ وه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(777, 'Genesis 28:17', 'Genesis', 28, 17, '&nbsp;هغه يرېدو او د ځان سره يې وفرمائيل، ”دا ځائ خو د يرې نه ډک دے. دا به خامخا د خُدائ پاک کور وى، دا به خامخا د آسمان دروازه وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(778, 'Genesis 28:18', 'Genesis', 28, 18, '&nbsp;کله چې يعقوب سحر وختى پاڅېدو، هغه کاڼے يې راواخستلو چې په کوم يې سر اېښے وو او د يو يادګار په توګه يې ودرولو. بيا هغۀ په دې باندې تېل واچول چې خُدائ پاک ته وقف شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(779, 'Genesis 28:19', 'Genesis', 28, 19, '&nbsp;هغۀ په هغه ځائ بيت‌ايل نوم کېښودو. دا ښار مخکښې د لوز په نوم مشهور وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(780, 'Genesis 28:20', 'Genesis', 28, 20, '&nbsp;بيا يعقوب د خُدائ پاک سره وعده وکړه، ”کۀ تۀ زما مل يې او په دې سفر کښې زما حِفاظت کوې او ما له خوړلو له روټۍ راکوې او اغوستلو له جامې راکوې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(781, 'Genesis 28:21', 'Genesis', 28, 21, '&nbsp;او کۀ زۀ په حِفاظت سره بيا د خپل پلار کور ته راشم، نو تۀ به زما خُدائ پاک يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(782, 'Genesis 28:22', 'Genesis', 28, 22, '&nbsp;دا د يادګار کاڼے چې کوم ما ودرولے دے، دا به هغه ځائ وى چې چرته به ستا عبادت کيږى او چې تۀ ما له څۀ راکوې د هغې لسمه برخه به زۀ خامخا تا له درکوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(783, 'Genesis 29:1', 'Genesis', 29, 1, '&nbsp;بيا يعقوب په خپل سفر روان وو او د نمرخاتۀ په طرف د خلقو مُلک ته لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(784, 'Genesis 29:2', 'Genesis', 29, 2, '&nbsp;چې څنګه هغۀ وکتل نو هغۀ په مېدان کښې يو کوهے وليدو او وې ليدل چې درې رَمې ورسره پرتې وې. هغه رَمو به د دې کوهى نه اوبۀ څښلې او د هغه کوهى په خولۀ يوه غټه تيږه پرته وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(785, 'Genesis 29:3', 'Genesis', 29, 3, '&nbsp;او چې کله به ټولې رَمې هلته راغونډې شوې، نو شپانو به هغه تيږه لرې کوله او اوبۀ به يې ورکولې. بيا به هغوئ هغه تيږه واپس په خپل ځائ د کوهى په خولۀ کېښودله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(786, 'Genesis 29:4', 'Genesis', 29, 4, '&nbsp;يعقوب د شپانو نه تپوس وکړو، ”زما وروڼو، تاسو د کوم ځائ يئ؟“ هغوئ جواب ورکړو، ”مونږ د حاران يُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(787, 'Genesis 29:5', 'Genesis', 29, 5, '&nbsp;هغۀ ترې تپوس وکړو، ”تاسو د نحور نمسے، لابن پېژنئ؟“ هغوئ ورته ووئيل، ”آو، مونږ يې پېژنو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(788, 'Genesis 29:6', 'Genesis', 29, 6, '&nbsp;هغۀ ترې تپوس وکړو، ”هغه څنګه دے؟“ هغوئ جواب ورکړو، ”هغه ښۀ دے، ګوره، دلته د هغۀ لور راحيل د خپلو رَمو سره راروانه ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(789, 'Genesis 29:7', 'Genesis', 29, 7, '&nbsp;يعقوب وفرمائيل، ”ګوره تر اوسه پورې نمر اوچت ولاړ دے او د رَمو د راغونډولو وخت لا نۀ دے، تاسو ولې اوبۀ نۀ ورکوئ او واپس يې څرولو له نۀ بوځئ؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(790, 'Genesis 29:8', 'Genesis', 29, 8, '&nbsp;هغوئ جواب ورکړو، ”مونږ داسې تر هغې پورې نۀ شُو کولے چې ټولې رَمې راغونډې نۀ وى. او چې کله هغه تيږه لرې کړے شى، نو بيا به مونږ رَمو له اوبۀ ورکوو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(791, 'Genesis 29:9', 'Genesis', 29, 9, '&nbsp;يعقوب لا د هغوئ سره خبرې کولې چې راحيل د خپل پلار د رَمې سره راورسېدله، ځکه چې هغه شپونکۍ وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(792, 'Genesis 29:10', 'Genesis', 29, 10, '&nbsp;چې کله يعقوب خپله د ماما لور راحيل د هغې د پلار د رَمې سره وليده، نو هغه کوهى له ورَغلو، د کوهى د خولې نه يې تيږه لرې کړه او د لابن رَمو له يې اوبۀ ورکړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(793, 'Genesis 29:11', 'Genesis', 29, 11, '&nbsp;بيا يعقوب، راحيل ښُکل کړه او د خوشحالۍ نه په ژړا شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(794, 'Genesis 29:12', 'Genesis', 29, 12, '&nbsp;هغۀ راحيل ته وفرمائيل، ”زۀ ستا د پلار رشته‌دار، د رِبقې زوئ يم.“ هغې منډه کړه چې خپل پلار ته ووائى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(795, 'Genesis 29:13', 'Genesis', 29, 13, '&nbsp;او چې کله لابن د خپل خورئى يعقوب په حقله واورېدل، نو هغۀ مِلاوېدو له ورمنډه کړه، هغۀ ته ورغاړه وتلو او ښُکل يې کړو او هغه يې کور ته دننه راوستلو. يعقوب لابن ته هغه هر څۀ وفرمائيل چې څۀ شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(796, 'Genesis 29:14', 'Genesis', 29, 14, '&nbsp;لابن ووئيل، ”په رښتيا سره، تۀ زما خپله وينه يې.“ يعقوب هلته پوره مياشت ايسار شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(797, 'Genesis 29:15', 'Genesis', 29, 15, '&nbsp;لابن يعقوب ته ووئيل، ”تا له صِرف زما د خپلوالۍ په وجه زما خِدمت کول نۀ دى په کار. ما ته ووايه، چې تۀ به څومره مزدورى غواړې؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(798, 'Genesis 29:16', 'Genesis', 29, 16, '&nbsp;نو د لابن دوه لوڼه وې، د مشرې نوم لِياه او د کشرې راحيل وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(799, 'Genesis 29:17', 'Genesis', 29, 17, '&nbsp;د لِياه سترګې ښُکلې وې، خو راحيل د بدن نه ښُکلې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(800, 'Genesis 29:18', 'Genesis', 29, 18, '&nbsp;يعقوب د راحيل سره مينه کوله، نو ځکه هغۀ وفرمائيل، ”زۀ به ستا د کشرې لور راحيل دپاره ستا اووۀ کاله خِدمت کوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');